// Strip Markdown symbols (Telegram does not render them) and split the reply into chunks of max 2,500 characters
const LIMIT = 2500;
let text = String($input.first().json.output || '').trim();

text = text
  .replace(/\*\*(.+?)\*\*/g, '$1')
  .replace(/__(.+?)__/g, '$1')
  .replace(/^#{1,6}\s*/gm, '')
  .replace(/^\s*-{3,}\s*$/gm, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const chunks = [];
let current = '';

const push = (piece, sep) => {
  if (!current) { current = piece; return; }
  if ((current + sep + piece).length <= LIMIT) { current += sep + piece; return; }
  chunks.push(current);
  current = piece;
};

for (const para of text.split(/\n{2,}/)) {
  if (para.length <= LIMIT) { push(para, '\n\n'); continue; }
  // Paragraph too long: split by line, then by word
  for (const line of para.split('\n')) {
    let part = line;
    while (part.length > LIMIT) {
      if (current) { chunks.push(current); current = ''; }
      let cut = part.lastIndexOf(' ', LIMIT);
      if (cut < LIMIT * 0.5) cut = LIMIT;
      chunks.push(part.slice(0, cut).trim());
      part = part.slice(cut).trim();
    }
    if (part) push(part, '\n');
  }
}
if (current) chunks.push(current);
if (chunks.length === 0) chunks.push('Sorry, I could not answer that. Please try again.');

return chunks.map((c, i) => ({
  json: { output: chunks.length > 1 ? `${c}\n\n(${i + 1}/${chunks.length})` : c },
  pairedItem: { item: 0 },
}));

// Convert the agent's lightweight markup into styled HTML, then build a multipart body
// that uploads it to Google Drive and converts it into a Google Doc in one request.
const input = $('Document Request').first().json;
const title = String(input.title || 'Document').trim() || 'Document';
const md = String(input.content || '').replace(/\r\n/g, '\n').trim();

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inline = (s) => esc(s)
  .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
  .replace(/(^|[\s(])_([^_]+?)_(?=$|[\s).,;:!?])/g, '$1<i>$2</i>');

// ---- Theme: change colors and fonts here ----
const C = { accent: '#1F3864', dark: '#1e293b', text: '#334155', sub: '#475569', muted: '#64748b', border: '#B4C6E7', thBg: '#D9E2F3' };
const F = 'font-family:Times New Roman,Times,serif;';
const S = {
  h1: F + 'font-size:20pt;font-weight:bold;color:' + C.accent + ';margin:0 0 4pt 0;',
  title: F + 'font-size:11pt;font-weight:bold;color:' + C.sub + ';margin:0 0 4pt 0;',
  info: F + 'font-size:11pt;color:' + C.muted + ';margin:0 0 2pt 0;',
  h2: F + 'font-size:12pt;font-weight:bold;color:' + C.accent + ';margin:14pt 0 0 0;',
  h3: F + 'font-size:11pt;font-weight:bold;color:' + C.dark + ';margin:10pt 0 2pt 0;',
  sub: F + 'font-size:11pt;font-weight:bold;color:' + C.accent + ';margin:0 0 4pt 0;',
  p: F + 'font-size:11pt;font-weight:normal;color:' + C.text + ';line-height:1.5;margin:0 0 8pt 0;',
  li: F + 'font-size:11pt;font-weight:normal;color:' + C.text + ';line-height:1.5;margin:0 0 3pt 0;',
  spacer: F + 'font-size:6pt;font-weight:normal;line-height:1;margin:0;',
  rowTable: 'border-collapse:collapse;width:100%;margin:10pt 0 2pt 0;border:none;',
  rowLeft: F + 'font-size:11pt;font-weight:bold;color:' + C.dark + ';border:none;padding:0;text-align:left;',
  rowRight: F + 'font-size:11pt;font-style:italic;color:' + C.muted + ';border:none;padding:0;text-align:right;',
  table: 'border-collapse:collapse;width:100%;margin:6pt 0 10pt 0;',
  th: F + 'font-size:11pt;font-weight:bold;color:' + C.accent + ';background-color:' + C.thBg + ';border:1px solid ' + C.border + ';padding:4pt;',
  td: F + 'font-size:11pt;color:' + C.text + ';border:1px solid ' + C.border + ';padding:4pt;'
};

// Horizontal rule followed by a small spacer paragraph, so Google Docs does not
// attach the line to the next bullet or paragraph
const LINE = '<hr><p style="' + S.spacer + '">&nbsp;</p>';

const out = [];
let para = [];
let table = [];
let olOpen = false;    // numbered list is open
let liOpen = false;    // last numbered item is still open (for nested bullets)
let subUlOpen = false; // nested bullets under a numbered item
let ulOpen = false;    // plain bullet list
let olCount = 0;       // last number in this section, so numbering continues
let inHeader = false;  // header block: after "# Title" until the first content line

const closeSub = () => { if (subUlOpen) { out.push('</ul>'); subUlOpen = false; } };
const closeLi = () => { closeSub(); if (liOpen) { out.push('</li>'); liOpen = false; } };
const closeOl = () => { closeLi(); if (olOpen) { out.push('</ol>'); olOpen = false; } };
const closeUl = () => { if (ulOpen) { out.push('</ul>'); ulOpen = false; } };
const flushLists = () => { closeOl(); closeUl(); };
const flushPara = () => { if (para.length) { out.push('<p style="' + S.p + '">' + para.map(inline).join('<br>') + '</p>'); para = []; } };
const cells = (r) => r.replace(/^\s*\|/, '').replace(/\|\s*$/, '').split('|').map((c) => c.trim());
const flushTable = () => {
  if (!table.length) return;
  const rows = table.filter((r) => !(/^[\s|:-]+$/.test(r) && r.includes('-')));
  let html = '<table style="' + S.table + '">';
  rows.forEach((r, i) => {
    const tag = i === 0 ? 'th' : 'td';
    html += '<tr>' + cells(r).map((c) => '<' + tag + ' style="' + S[tag] + '">' + inline(c) + '</' + tag + '>').join('') + '</tr>';
  });
  out.push(html + '</table>');
  table = [];
};
const flushAll = () => { flushPara(); flushLists(); flushTable(); };

// Divider under the header block (name, role, contact line)
const closeHeader = () => { if (inHeader) { flushPara(); out.push(LINE); inHeader = false; } };

// "left || right" line: bold item title on the left, italic note right-aligned (borderless table)
const rowLine = (left, right) => '<table style="' + S.rowTable + '"><tr><td style="' + S.rowLeft + '">' + inline(left) + '</td><td style="' + S.rowRight + '">' + inline(right) + '</td></tr></table>';

// If the content does not start with a "# Title", use the document title
if (!/^#\s/.test(md)) { out.push('<h1 style="' + S.h1 + '">' + esc(title.toUpperCase()) + '</h1>'); inHeader = true; }

for (const raw of md.split('\n')) {
  const t = raw.trim();

  // Blank line closes paragraphs and tables, but does NOT break a numbered list
  if (!t) { flushPara(); flushTable(); continue; }

  // Header block: "> role/subtitle" and "@ small info line"
  if (inHeader) {
    if (t.startsWith('> ')) { out.push('<p style="' + S.title + '">' + inline(t.slice(2)) + '</p>'); continue; }
    if (t.startsWith('@ ')) { out.push('<p style="' + S.info + '">' + inline(t.slice(2)) + '</p>'); continue; }
    closeHeader();
  }

  if (t.startsWith('|')) { flushPara(); flushLists(); table.push(t); continue; }
  flushTable();

  let m = t.match(/^(#{1,3})\s+(.*)$/);
  if (m) {
    flushAll();
    olCount = 0; // new section, numbering restarts at 1
    const lv = m[1].length;
    const text = m[2];
    if (lv === 1) { out.push('<h1 style="' + S.h1 + '">' + inline(text.toUpperCase()) + '</h1>'); inHeader = true; continue; }
    if (lv === 2) { out.push('<h2 style="' + S.h2 + '">' + inline(text.toUpperCase()) + '</h2>'); out.push(LINE); continue; }
    const parts = text.split(/\s*\|\|\s*/);
    if (parts.length > 1) out.push(rowLine(parts[0], parts.slice(1).join(' ')));
    else out.push('<h3 style="' + S.h3 + '">' + inline(text) + '</h3>');
    continue;
  }

  // "> subtitle" in accent color (for example a company name under a job title)
  if (t.startsWith('> ')) { flushPara(); flushLists(); out.push('<p style="' + S.sub + '">' + inline(t.slice(2)) + '</p>'); continue; }
  // "@ small muted info line"
  if (t.startsWith('@ ')) { flushPara(); flushLists(); out.push('<p style="' + S.info + '">' + inline(t.slice(2)) + '</p>'); continue; }

  m = t.match(/^\d+[.)]\s+(.*)$/);
  if (m) {
    flushPara(); closeUl(); closeLi();
    if (!olOpen) { out.push('<ol' + (olCount ? ' start="' + (olCount + 1) + '"' : '') + '>'); olOpen = true; }
    olCount++;
    out.push('<li style="' + S.li + '">' + inline(m[1]));
    liOpen = true;
    continue;
  }

  m = t.match(/^[-*•]\s+(.*)$/);
  if (m) {
    flushPara();
    if (olOpen && liOpen) {
      // A bullet right under a numbered item becomes a nested sub-point (numbering stays continuous)
      if (!subUlOpen) { out.push('<ul>'); subUlOpen = true; }
      out.push('<li style="' + S.li + '">' + inline(m[1]) + '</li>');
    } else {
      closeOl();
      if (!ulOpen) { out.push('<ul>'); ulOpen = true; }
      out.push('<li style="' + S.li + '">' + inline(m[1]) + '</li>');
    }
    continue;
  }

  if (/^-{3,}$/.test(t)) { flushAll(); continue; }

  // Plain "left || right" line
  if (/\s\|\|\s/.test(t)) { flushPara(); flushLists(); const p = t.split(/\s*\|\|\s*/); out.push(rowLine(p[0], p.slice(1).join(' '))); continue; }

  flushLists();
  para.push(t);
}
flushAll();
closeHeader();

const html = '<html><head><meta charset="UTF-8"></head><body>' + out.join('\n') + '</body></html>';
const boundary = 'n8nDocBoundary7f3a';
const meta = JSON.stringify({ name: title, mimeType: 'application/vnd.google-apps.document' });
const body = '--' + boundary + '\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n' + meta + '\r\n--' + boundary + '\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n' + html + '\r\n--' + boundary + '--';

return [{ json: { body, boundary } }];
